Here's a TypeScript pagination utility:

```typescript
interface PaginationResult<T> {
  data: T[]
  page: number
  limit: number
  total: number
  totalPages: number
  hasNext: boolean
  hasPrev: boolean
}

function paginate<T>(
  items: T[],
  page: number = 1,
  limit: number = 20
): PaginationResult<T> {
  const offset = (page - 1) * limit
  const total = items.length
  const totalPages = Math.ceil(total / limit)

  return {
    data: items.slice(offset, offset + limit),
    page,
    limit,
    total,
    totalPages,
    hasNext: page < totalPages,
    hasPrev: page > 1,
  }
}

// Async version for database queries
async function paginateQuery<T>(
  query: (skip: number, limit: number) => Promise<T[]>,
  countQuery: () => Promise<number>,
  page: number = 1,
  limit: number = 20
): Promise<PaginationResult<T>> {
  const offset = (page - 1) * limit
  const [data, total] = await Promise.all([
    query(offset, limit),
    countQuery(),
  ])

  return {
    data,
    page,
    limit,
    total,
    totalPages: Math.ceil(total / limit),
    hasNext: page < Math.ceil(total / limit),
    hasPrev: page > 1,
  }
}

export { paginate, paginateQuery, PaginationResult }
```

Usage:
```typescript
const result = paginate(allProducts, 2, 10)
// Returns page 2 with 10 items per page
