Here's a JavaScript function to validate Nigerian phone numbers:

```javascript
/**
 * Validate and format Nigerian phone numbers
 * Supports: 080XXXXXXXX, 234XXXXXXXXX, +234XXXXXXXXX
 * 
 * @param phone - Phone number string to validate
 * @returns Object with isValid, formatted, and error
 */
function validateNigerianPhone(phone) {
  // Remove spaces, dashes, and parentheses
  const cleaned = phone.replace(/[\s()-]/g, '')

  // Remove leading + if present
  const withoutPlus = cleaned.replace(/^\+/, '')

  // Pattern 1: Starts with 0 (local format) - 080XXXXXXXX, 070XXXXXXXX, etc.
  if (/^0[789][01]\d{8}$/.test(withoutPlus)) {
    return {
      isValid: true,
      formatted: withoutPlus,
      international: '234' + withoutPlus.slice(1),
      error: null
    }
  }

  // Pattern 2: Starts with 234 (international without +)
  if (/^234[789][01]\d{8}$/.test(withoutPlus)) {
    return {
      isValid: true,
      formatted: '0' + withoutPlus.slice(3),
      international: withoutPlus,
      error: null
    }
  }

  return {
    isValid: false,
    formatted: null,
    international: null,
    error: 'Invalid Nigerian phone number. Use format: 080XXXXXXXX or 234XXXXXXXXX'
  }
}

// Usage
console.log(validateNigerianPhone('08028687857'))
// { isValid: true, formatted: '08028687857', international: '2348028687857' }

console.log(validateNigerianPhone('+234 703 617 0795'))
// { isValid: true, formatted: '07036170795', international: '2347036170795' }

console.log(validateNigerianPhone('12345'))
// { isValid: false, error: 'Invalid Nigerian phone number...' }
```

Supports all Nigerian networks: MTN (0803, 0806, 0703, 0706, 0813, 0816, 0814, 0903, 0906), Glo (0805, 0807, 0705, 0815, 0811, 0905), Airtel (0802, 0808, 0708, 0812, 0701, 0901, 0907), 9mobile (0809, 0817, 0818, 0908, 0909).

Here's a TypeScript React hook for localStorage:

```typescript
import { useState, useEffect, useCallback } from 'react'

function useLocalStorage<T>(
  key: string,
  initialValue: T
): [T, (value: T | ((prev: T) => T)) => void, () => void] {
  // Get from localStorage on mount
  const [storedValue, setStoredValue] = useState<T>(() => {
    if (typeof window === 'undefined') return initialValue

    try {
      const item = window.localStorage.getItem(key)
      return item ? JSON.parse(item) : initialValue
    } catch (error) {
      console.error(`Error reading localStorage key "${key}":`, error)
      return initialValue
    }
  })

  // Update localStorage when value changes
  const setValue = useCallback(
    (value: T | ((prev: T) => T)) => {
      setStoredValue(prev => {
        const newValue = value instanceof Function ? value(prev) : value

        try {
          window.localStorage.setItem(key, JSON.stringify(newValue))
        } catch (error) {
          console.error(`Error setting localStorage key "${key}":`, error)
        }

        return newValue
      })
    },
    [key]
  )

  // Remove from localStorage
  const remove = useCallback(() => {
    try {
      window.localStorage.removeItem(key)
      setStoredValue(initialValue)
    } catch (error) {
      console.error(`Error removing localStorage key "${key}":`, error)
    }
  }, [key, initialValue])

  return [storedValue, setValue, remove]
}

export default useLocalStorage
```

Usage:
```typescript
const [name, setName, removeName] = useLocalStorage('username', 'Guest')
const [settings, setSettings] = useLocalStorage('appSettings', { theme: 'dark', lang: 'en' })
```

This handles SSR (server-side rendering), JSON serialization, function updates, and errors gracefully.

Here's a complete CRUD API using Next.js API routes:

```typescript
// pages/api/products/index.ts
import type { NextApiRequest, NextApiResponse } from 'next'

// In-memory store (replace with database)
let products: Product[] = []

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  switch (req.method) {
    case 'GET':
      // List all products with optional filtering
      const { category, search } = req.query
      let filtered = products
      if (category) filtered = filtered.filter(p => p.category === category)
      if (search) filtered = filtered.filter(p =>
        p.name.toLowerCase().includes((search as string).toLowerCase())
      )
      return res.status(200).json(filtered)

    case 'POST':
      // Create new product
      const newProduct = {
        id: Date.now().toString(),
        ...req.body,
        createdAt: new Date(),
        updatedAt: new Date(),
      }
      products.push(newProduct)
      return res.status(201).json(newProduct)

    default:
      res.setHeader('Allow', ['GET', 'POST'])
      return res.status(405).end('Method Not Allowed')
  }
}
```

```typescript
// pages/api/products/[id].ts
export default async function handler(req, res) {
  const { id } = req.query
  const index = products.findIndex(p => p.id === id)

  if (index === -1) return res.status(404).json({ error: 'Not found' })

  switch (req.method) {
    case 'GET':
      return res.status(200).json(products[index])

    case 'PUT':
      products[index] = {
        ...products[index],
        ...req.body,
        updatedAt: new Date(),
      }
      return res.status(200).json(products[index])

    case 'DELETE':
      products.splice(index, 1)
      return res.status(204).end()

    default:
      res.setHeader('Allow', ['GET', 'PUT', 'DELETE'])
      return res.status(405).end('Method Not Allowed')
  }
}
```

This gives you full CRUD: GET (list), POST (create), GET /:id, PUT /:id, DELETE /:id. Replace the in-memory array with a real database (MongoDB, PostgreSQL, etc.) for production.

Here's a Python script for currency conversion:

```python
import requests
import os
from typing import Dict, Optional

class CurrencyConverter:
    """Convert between NGN and USD using live exchange rates."""

    def __init__(self, api_key: Optional[str] = None):
        self.api_key = api_key or os.getenv('EXCHANGE_RATE_API_KEY')
        self.base_url = 'https://v6.exchangerate-api.com/v6'
        self.rates: Dict[str, float] = {}

    def fetch_rates(self, base: str = 'USD') -> Dict[str, float]:
        """Fetch latest exchange rates."""
        if self.api_key:
            url = f'{self.base_url}/{self.api_key}/latest/{base}'
        else:
            # Free API without key
            url = f'https://open.er-api.com/v6/latest/{base}'

        response = requests.get(url, timeout=10)
        response.raise_for_status()
        data = response.json()
        self.rates = data.get('rates', {})
        return self.rates

    def ngn_to_usd(self, ngn_amount: float) -> float:
        """Convert Naira to USD."""
        if not self.rates:
            self.fetch_rates('USD')
        ngn_rate = self.rates.get('NGN', 0)
        if ngn_rate == 0:
            raise ValueError('NGN rate not available')
        return round(ngn_amount / ngn_rate, 2)

    def usd_to_ngn(self, usd_amount: float) -> float:
        """Convert USD to Naira."""
        if not self.rates:
            self.fetch_rates('USD')
        ngn_rate = self.rates.get('NGN', 0)
        if ngn_rate == 0:
            raise ValueError('NGN rate not available')
        return round(usd_amount * ngn_rate, 2)

# Usage
if __name__ == '__main__':
    converter = CurrencyConverter()

    # Convert ₦25,000 to USD
    usd = converter.ngn_to_usd(25000)
    print(f'₦25,000 = ${usd}')

    # Convert $100 to NGN
    ngn = converter.usd_to_ngn(100)
    print(f'$100 = ₦{ngn:,.0f}')
```

Uses the free exchangerate-api.com (no key needed for basic usage). For production, get a free API key for higher limits.

