Here's a TypeScript price formatter for NGN/USD:

```typescript
/**
 * Format prices for Nigerian and international display
 * Supports NGN, USD, and dual-currency formatting
 */

class PriceFormatter {
  private exchangeRate: number

  constructor(exchangeRate: number = 1500) {
    // Default rate: 1 USD = ₦1500 (update regularly)
    this.exchangeRate = exchangeRate
  }

  setRate(rate: number) {
    this.exchangeRate = rate
  }

  formatNGN(amount: number): string {
    return `₦${amount.toLocaleString('en-NG', {
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    })}`
  }

  formatUSD(amount: number): string {
    return `$${amount.toLocaleString('en-US', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    })}`
  }

  ngnToUSD(ngn: number): string {
    return this.formatUSD(ngn / this.exchangeRate)
  }

  usdToNGN(usd: number): string {
    return this.formatNGN(usd * this.exchangeRate)
  }

  dual(ngn: number): string {
    const usd = ngn / this.exchangeRate
    return `${this.formatNGN(ngn)} (${this.formatUSD(usd)})`
  }

  // For pay-what-you-want or tiered pricing
  formatTier(low: number, high: number, currency: 'NGN' | 'USD' = 'NGN'): string {
    if (currency === 'NGN') {
      return `${this.formatNGN(low)} - ${this.formatNGN(high)}`
    }
    return `${this.formatUSD(low)} - ${this.formatUSD(high)}`
  }
}

// Usage
const price = new PriceFormatter(1500)

console.log(price.formatNGN(25000))      // ₦25,000
console.log(price.formatUSD(16.67))      // $16.67
console.log(price.ngnToUSD(25000))       // $16.67
console.log(price.usdToNGN(100))         // ₦150,000
console.log(price.dual(25000))           // ₦25,000 ($16.67)
console.log(price.formatTier(15000, 50000)) // ₦15,000 - ₦50,000
```

Update the exchange rate regularly. For real-time rates, fetch from an API like exchangerate-api.com.

