Here's a TypeScript rate limiter for Next.js API routes:

```typescript
// lib/rateLimit.ts
import type { NextApiRequest, NextApiResponse } from 'next'

interface RateLimitOptions {
  windowMs: number    // Time window in milliseconds
  maxRequests: number // Max requests per window
  message?: string
}

interface RateLimitEntry {
  count: number
  resetTime: number
}

// In-memory store (use Redis for production)
const store = new Map<string, RateLimitEntry>()

export function rateLimit(options: RateLimitOptions) {
  const { windowMs, maxRequests, message = 'Too many requests' } = options

  return function(
    handler: (req: NextApiRequest, res: NextApiResponse) => Promise<any>
  ) {
    return async (req: NextApiRequest, res: NextApiResponse) => {
      // Get client identifier (IP + optional user ID)
      const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress || 'unknown'
      const userId = (req as any).user?.id || ''
      const key = `${ip}:${userId}`

      const now = Date.now()
      const entry = store.get(key)

      if (!entry || now > entry.resetTime) {
        // New window
        store.set(key, {
          count: 1,
          resetTime: now + windowMs
        })
      } else {
        // Existing window
        entry.count++

        if (entry.count > maxRequests) {
          const resetSeconds = Math.ceil((entry.resetTime - now) / 1000)
          res.setHeader('Retry-After', resetSeconds.toString())
          res.setHeader('X-RateLimit-Limit', maxRequests.toString())
          res.setHeader('X-RateLimit-Remaining', '0')
          res.setHeader('X-RateLimit-Reset', entry.resetTime.toString())

          return res.status(429).json({
            error: message,
            retryAfter: resetSeconds
          })
        }
      }

      const current = store.get(key)!
      res.setHeader('X-RateLimit-Limit', maxRequests.toString())
      res.setHeader('X-RateLimit-Remaining', String(maxRequests - current.count))

      // Clean up expired entries periodically
      if (store.size > 10000) {
        for (const [k, v] of store) {
          if (now > v.resetTime) store.delete(k)
        }
      }

      return handler(req, res)
    }
  }
}

// Usage in API route:
// import { rateLimit } from '../../../lib/rateLimit'
// 
// export default rateLimit({
//   windowMs: 60 * 1000,  // 1 minute
//   maxRequests: 30       // 30 requests per minute
// })(async (req, res) => {
//   // Your handler here
// })
```

For production with multiple servers, use Redis instead of in-memory Map.

Here's a JavaScript order ID generator:

```javascript
/**
 * Generate unique order IDs with timestamps and random suffixes.
 * Format: HARZ-YYYYMMDD-HHMMSS-XXXX
 * Example: HARZ-20260802-143052-A7B2
 */

class OrderIdGenerator {
  private counter: number = 0
  private lastTimestamp: string = ''

  /**
   * Generate a unique order ID
   */
  generate(prefix: string = 'HARZ'): string {
    const now = new Date()

    // Date component: YYYYMMDD
    const date = now.getFullYear().toString() +
      String(now.getMonth() + 1).padStart(2, '0') +
      String(now.getDate()).padStart(2, '0')

    // Time component: HHMMSS
    const time = String(now.getHours()).padStart(2, '0') +
      String(now.getMinutes()).padStart(2, '0') +
      String(now.getSeconds()).padStart(2, '0')

    // Random suffix for uniqueness
    const random = Math.random().toString(36).substring(2, 6).toUpperCase()

    return `${prefix}-${date}-${time}-${random}`
  }

  /**
   * Generate a shorter order ID (for receipts)
   * Format: HZ-XXXXXX
   */
  generateShort(): string {
    const timestamp = Date.now().toString(36).toUpperCase()
    const random = Math.random().toString(36).substring(2, 5).toUpperCase()
    return `HZ-${timestamp.slice(-4)}${random}`
  }

  /**
   * Generate a sequential order ID with counter
   * Format: HARZ-000001
   */
  generateSequential(): string {
    this.counter++
    return `HARZ-${String(this.counter).padStart(6, '0')}`
  }

  /**
   * Validate an order ID format
   */
  isValid(orderId: string): boolean {
    const pattern = /^HARZ-\d{8}-\d{6}-[A-Z0-9]{4}$/
    return pattern.test(orderId)
  }

  /**
   * Extract date from order ID
   */
  getDate(orderId: string): Date | null {
    const match = orderId.match(/^HARZ-(\d{4})(\d{2})(\d{2})/)
    if (!match) return null
    return new Date(parseInt(match[1]), parseInt(match[2]) - 1, parseInt(match[3]))
  }
}

// Usage
const generator = new OrderIdGenerator()

console.log(generator.generate())        // HARZ-20260802-143052-A7B2
console.log(generator.generateShort())   // HZ-K7B2X9
console.log(generator.generateSequential()) // HARZ-000001
console.log(generator.isValid('HARZ-20260802-143052-A7B2')) // true
console.log(generator.getDate('HARZ-20260802-143052-A7B2'))  // 2026-08-02
```

The full format includes date, time, and random suffix for uniqueness. Use `generate()` for main orders, `generateShort()` for receipts, and `generateSequential()` for invoice numbers.

Here's a TypeScript validator for Nigerian customer data:

```typescript
interface ValidationResult {
  isValid: boolean
  error?: string
  formatted?: string
}

/**
 * Validate email address
 */
function validateEmail(email: string): ValidationResult {
  if (!email || email.trim() === '') {
    return { isValid: false, error: 'Email is required' }
  }

  // Standard email regex
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
  if (!emailRegex.test(email)) {
    return { isValid: false, error: 'Invalid email format' }
  }

  // Check common Nigerian email domains
  const lowerEmail = email.toLowerCase()
  const commonDomains = ['gmail.com', 'yahoo.com', 'outlook.com', 'hotmail.com']
  const domain = lowerEmail.split('@')[1]

  if (!commonDomains.includes(domain) && !domain.includes('.')) {
    return { isValid: false, error: 'Please use a valid email (Gmail, Yahoo, etc.)' }
  }

  return { isValid: true, formatted: lowerEmail }
}

/**
 * Validate Nigerian phone number
 */
function validateNigerianPhone(phone: string): ValidationResult {
  if (!phone || phone.trim() === '') {
    return { isValid: false, error: 'Phone number is required' }
  }

  // Remove spaces, dashes, parentheses
  const cleaned = phone.replace(/[\s()-]/g, '').replace(/^\+/, '')

  // Nigerian prefixes: 070, 080, 081, 090, 091
  // International: 23470, 23480, 23481, 23490, 23491

  let normalized = cleaned

  // Convert 234 format to 0X format
  if (cleaned.startsWith('234') && cleaned.length === 13) {
    normalized = '0' + cleaned.slice(3)
  }

  // Validate length (11 digits starting with 0)
  if (normalized.length !== 11 || !normalized.startsWith('0')) {
    return { isValid: false, error: 'Invalid phone number. Use format: 080XXXXXXXX' }
  }

  // Check valid prefix
  const validPrefixes = ['070', '080', '081', '090', '091']
  const prefix = normalized.substring(0, 3)
  if (!validPrefixes.includes(prefix)) {
    return { isValid: false, error: 'Invalid Nigerian phone prefix' }
  }

  // International format
  const international = '234' + normalized.slice(1)

  return {
    isValid: true,
    formatted: normalized,
    international: international
  } as any
}

/**
 * Validate customer form data
 */
interface CustomerData {
  name: string
  email: string
  phone: string
}

function validateCustomer(data: CustomerData): {
  isValid: boolean
  errors: Record<string, string>
  data: CustomerData
} {
  const errors: Record<string, string> = {}
  const cleaned: CustomerData = { name: '', email: '', phone: '' }

  // Validate name
  if (!data.name || data.name.trim().length < 2) {
    errors.name = 'Please enter your full name'
  } else {
    cleaned.name = data.name.trim()
  }

  // Validate email
  const emailResult = validateEmail(data.email)
  if (!emailResult.isValid) {
    errors.email = emailResult.error!
  } else {
    cleaned.email = emailResult.formatted!
  }

  // Validate phone
  const phoneResult = validateNigerianPhone(data.phone)
  if (!phoneResult.isValid) {
    errors.phone = phoneResult.error!
  } else {
    cleaned.phone = phoneResult.formatted!
  }

  return {
    isValid: Object.keys(errors).length === 0,
    errors,
    data: cleaned
  }
}

export { validateEmail, validateNigerianPhone, validateCustomer, ValidationResult, CustomerData }
```

Validates email format, Nigerian phone numbers (070/080/081/090/091 prefixes), and cleans/formats the data.

