      <div className="space-y-4">
        <input value={name} onChange={e => setName(e.target.value)} placeholder="Full Name" className="w-full px-4 py-3 rounded-xl bg-gray-800 border border-gray-700" />
        {errors.name && <p className="text-red-400 text-sm">{errors.name}</p>}

        <input value={email} onChange={e => setEmail(e.target.value)} placeholder="Email Address" type="email" className="w-full px-4 py-3 rounded-xl bg-gray-800 border border-gray-700" />
        {errors.email && <p className="text-red-400 text-sm">{errors.email}</p>}

        <input value={phone} onChange={e => setPhone(e.target.value)} placeholder="Phone (080XXXXXXXX)" className="w-full px-4 py-3 rounded-xl bg-gray-800 border border-gray-700" />
        {errors.phone && <p className="text-red-400 text-sm">{errors.phone}</p>}
      </div>

      {/* Payment Method */}
      <div className="space-y-2">
        <label className="text-sm text-gray-400">Select Payment Method</label>
        {paymentOptions.map(opt => (
          <button key={opt.id} type="button" onClick={() => setMethod(opt.id)} className={`w-full flex items-center gap-3 p-4 rounded-xl border transition-all ${method === opt.id ? 'border-purple-500 bg-purple-500/10' : 'border-gray-700 hover:border-gray-600'}`}>
            <span className="text-2xl">{opt.icon}</span>
            <div className="text-left flex-1">
              <div className="font-semibold">{opt.label}</div>
              <div className="text-xs text-gray-400">{opt.desc}</div>
            </div>
            {method === opt.id && <span className="text-purple-400">✓</span>}
          </button>
        ))}
      </div>

      <button type="submit" className="w-full py-4 bg-purple-600 hover:bg-purple-700 rounded-xl font-bold text-lg">
        Complete Purchase - ₦{totalAmount.toLocaleString()}
      </button>
      <p className="text-center text-xs text-gray-400">🔒 Secure checkout | 7-day money-back guarantee</p>
    </form>
  )
}
